import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.l66uSLlc.js";const g=JSON.parse(`{"title":"Decisions","description":"What has been decided about Noto's direction, when, and what is still open.","frontmatter":{"title":"Decisions","description":"What has been decided about Noto's direction, when, and what is still open."},"headers":[],"relativePath":"direction/decisions.md","filePath":"direction/decisions.md","lastUpdated":1790685849000}`),n={name:"direction/decisions.md"};function d(s,e,i,h,l,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>A decision is recorded here when it is made, with its date and where it happened. An open question stays open until someone with the authority to answer it does. Recommendations are the reviewer&#39;s; they are not decisions.</p><h2 id="decided" tabindex="-1">Decided <a class="header-anchor" href="#decided" aria-label="Permalink to &quot;Decided {#decided}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Decision</th><th>Where</th></tr></thead><tbody><tr><td>2026-09-27</td><td><code>@roobli/md</code> is Noto&#39;s default Markdown engine. <code>NOTO_MARKDOWN_ENGINE=micromark</code> remains as an escape hatch.</td><td><a href="https://github.com/roobli/Noto/pull/282" target="_blank" rel="noreferrer">Noto#282</a>, shipped in <code>v0.0.2-alpha.112</code></td></tr><tr><td>2026-09</td><td>Leaving alpha requires two gates: <code>@roobli/md</code> on by default, and macOS notarization. Release readiness is signed off by the maintainer who owns it, not declared by whoever cuts the tag. Extended by D2.</td><td>Maintainers</td></tr><tr><td>2026-09</td><td>Nested emphasis is capped at thirty-seven levels on purpose. No release exists only to raise the cap.</td><td>Maintainers; <code>MAX_MARK_NEST</code> in <code>src/shared/markdown/v3/pm/from-engine.ts</code></td></tr><tr><td>2026-09</td><td>Public work lives in the roobli organization. No private note content is ever published; fixtures are synthetic.</td><td>Maintainers</td></tr><tr><td>2026-09-29</td><td>Remove private-vault material from every public tree: design records, test data, local paths, screenshots.</td><td>Owner; <a href="https://github.com/roobli/Noto/pull/289" target="_blank" rel="noreferrer">Noto#289</a>, <a href="https://github.com/roobli/md/pull/21" target="_blank" rel="noreferrer">md#21</a>, <a href="https://github.com/roobli/holt/pull/3" target="_blank" rel="noreferrer">holt#3</a>, <a href="https://github.com/roobli/canvas/pull/1" target="_blank" rel="noreferrer">canvas#1</a></td></tr><tr><td>2026-09-29</td><td><strong>D1.</strong> Repair the Stable channel now. A version with a prerelease component is a prerelease whatever GitHub says; the release workflow creates and corrects releases from the tag; existing releases are re-flagged.</td><td>Owner; <a href="https://github.com/roobli/Noto/pull/289" target="_blank" rel="noreferrer">Noto#289</a></td></tr><tr><td>2026-09-29</td><td><strong>D2.</strong> The first non-alpha release requires <code>@roobli/md</code> on by default, macOS notarization, a repaired Stable channel, performance numbers measured on the current engine, and a stated Intel Mac position. Windows signing and the rest of <a href="./roadmap#now">Now</a> may follow in the next release.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D3.</strong> The first non-alpha version is <code>0.1.0</code>.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D4.</strong> Three release tracks: CI builds on every merge as workflow artifacts; alphas at most weekly, each with written notes, on Testing; releases per milestone, on Stable and Testing.</td><td>Owner; <a href="./roadmap#releases">how releases work</a></td></tr><tr><td>2026-09-29</td><td><strong>D5.</strong> The headline is <strong>&quot;Edit the page. Keep the file.&quot;</strong>, with &quot;A Markdown editor that edits the rendered document and keeps the file byte for byte&quot; beneath it as the explanation.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D6.</strong> <code>@roobli/canvas</code> is frozen and labelled experimental until Noto decides to host canvas documents. holt stays outside Noto&#39;s story and is labelled a personal companion, published as is. <code>@roobli/md</code> goes to npm when its contract reaches v1, not before.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D7.</strong> The Windows signing route is chosen after checking price and eligibility at the time of purchase, and recorded here with its reasons.</td><td>Owner; chosen in D15</td></tr><tr><td>2026-09-29</td><td><strong>D8.</strong> Every release builds for Intel Macs as well, and until one does, the pages say so. Refined the same day: a separate Intel zip cross-built on the Apple silicon runner rather than a universal binary, since it is half the download and the updater feed already chooses by architecture.</td><td>Owner; <a href="https://github.com/roobli/Noto/pull/289" target="_blank" rel="noreferrer">Noto#289</a>, <a href="https://github.com/roobli/Noto/pull/291" target="_blank" rel="noreferrer">Noto#291</a></td></tr><tr><td>2026-09-29</td><td><strong>D9.</strong> English is the working language of every repository. User guides on this site get Chinese translations once the English is stable. A repository whose README is in another language opens with an English summary.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D10.</strong> This site&#39;s prose and images are CC BY 4.0; its code is MIT.</td><td>Owner; <a href="https://github.com/roobli/Noto.docs/blob/main/LICENSE" target="_blank" rel="noreferrer"><code>LICENSE</code></a></td></tr><tr><td>2026-09-29</td><td><strong>D11.</strong> Saving automatically stays off by default for <code>0.1.0</code>, and is reconsidered once the cost of saving a very large file is bounded.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D12.</strong> The micromark escape hatch is removed after two releases on Stable in which no reported fidelity problem needed it, with the golden corpus green on the default engine throughout.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D13.</strong> The web track runs as planned: W0 and the groundwork now, W1 and W2 after <code>0.1.0</code>. W3, Noto for the web as a product surface, is decided after W2 has been used.</td><td>Owner; <a href="./roadmap#web">Noto on the web</a></td></tr><tr><td>2026-09-29</td><td><strong>D14.</strong> The editor core stays AGPL-3.0-only, including on the web. <code>@roobli/md</code> stays MIT as the layer meant for other hosts. Revisit only if a real embedder appears.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td>Purge the private material from git history as well as from the current trees, and ask GitHub to drop cached views of the old commits.</td><td>Owner</td></tr><tr><td>2026-09-29</td><td><strong>D15.</strong> Windows builds are signed through the <a href="https://signpath.org/" target="_blank" rel="noreferrer">SignPath Foundation</a> programme for open-source projects: free, the key held in their HSM, signing driven from the release workflow on GitHub Actions. Azure Artifact Signing was ruled out on eligibility, which is limited to individuals in the US and Canada and to businesses in the US, Canada, the EU and the UK. A certificate on a hardware token remains the fallback.</td><td>Owner; the application is the next step</td></tr></tbody></table><h2 id="open" tabindex="-1">Open <a class="header-anchor" href="#open" aria-label="Permalink to &quot;Open {#open}&quot;">​</a></h2><h3 id="d16-code-of-conduct-contact" tabindex="-1">D16. Code of conduct contact <a class="header-anchor" href="#d16-code-of-conduct-contact" aria-label="Permalink to &quot;D16. Code of conduct contact&quot;">​</a></h3><p>The organization&#39;s code of conduct needs a reporting contact, an address or a named maintainer, before it can be published.</p>',7)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
